// To provide test host tools the current android jar file to execute the host test
filegroup {
    name: "current_android_jar",
    srcs: [
        "public/android.jar",
    ],
    visibility: [
        "//system/apex/apexer", // for apexer_host_test_tools
        "//system/apex/tests/testdata/sharedlibs/build:__subpackages__",
        "//system/apex/tools", // for apex_compression_test_host_tools
        // Access to current_android_jar is necessary for cronet. Chromium's
        // jni_generator.py requires the android.jar to be passed via
        // --jar-file. At the time the android.jar is used, jni_generator.py
        // runs inside a cc_genrule (it generates .h files), so a java_import
        // generated by the prebuilt_apis "sdk" target cannot be used.
        "//external/cronet:__subpackages__",
        // In order to test aapt2, it needs to manually build a test app for
        // which it needs access to the current android jar.
        "//frameworks/base/tools/aapt2/integration-tests/FlaggedResourcesTest",
    ],
}

